// Build the APK's offline copy of the office's terminal runtime. The parity test
// compares the generated bytes, including the same core WASM the web build uses.
import { copyFileSync, mkdirSync, writeFileSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { buildSync } from 'esbuild';

const root = fileURLToPath(new URL('../', import.meta.url));
const assets = path.join(root, 'android/app/src/main/assets');
const vendor = path.join(assets, 'terminal/vendor');

export const vendoredPaths = () => [
  [path.join(root, 'node_modules/@wterm/ghostty/LICENSE'), path.join(assets, 'licenses/wterm-LICENSE.txt')],
  [path.join(root, 'node_modules/@wterm/ghostty/wasm/ghostty-vt.wasm'), path.join(vendor, 'ghostty-vt.wasm')],
];

export function builtFiles() {
  const { outputFiles } = buildSync({
    absWorkingDir: root,
    entryPoints: ['src/client/term-engine/android-terminal.ts'],
    outdir: vendor,
    bundle: true,
    format: 'esm',
    minify: true,
    target: 'es2020',
    loader: { '.wasm': 'file' },
    assetNames: '[name]',
    publicPath: './vendor',
    write: false,
  });
  return outputFiles.filter((file) => !file.path.endsWith('.wasm')).map((file) => [file.path, file.text]);
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  mkdirSync(vendor, { recursive: true });
  for (const [from, to] of vendoredPaths()) copyFileSync(from, to);
  for (const [to, contents] of builtFiles()) writeFileSync(to, contents);
}
